// binarySearch يرجع فهرس الهدف أو -1 إذا لم يوجد
func binarySearch(arr []int, target int) int {
	low, high := 0, len(arr)-1
	for low <= high {
		mid := low + (high-low)/2 // تجنب تجاوز العدد الصحيح
		if arr[mid] == target {
			return mid
		} else if arr[mid] < target {
			low = mid + 1 // ابحث في النصف الأيمن
		} else {
			high = mid - 1 // ابحث في النصف الأيسر
		}
	}
	return -1
}

func main() {
	data := []int{2, 5, 8, 12, 16, 23, 38, 56, 72, 91}
	targets := []int{23, 5, 99}
	for _, t := range targets {
		fmt.Printf("%d at index %d\n", t, binarySearch(data, t))
	}
}

