// TreeNode: عقدة الشجرة تحتوي قيمة ومؤشرين لليسار واليمين
type TreeNode struct {
    value int
    left  *TreeNode
    right *TreeNode
}

// Insert: إدراج قيمة في الشجرة مع الحفاظ على خاصية البحث الثنائي
func (n *TreeNode) Insert(val int) *TreeNode {
    if n == nil {
        return &TreeNode{value: val}
    }
    if val < n.value {
        n.left = n.left.Insert(val)
    } else {
        n.right = n.right.Insert(val)
    }
    return n
}

// InOrder: اجتياز بالترتيب (يسار، جذر، يمين) يعطي القيم مرتبة تصاعدياً
func (n *TreeNode) InOrder() {
    if n == nil {
        return
    }
    n.left.InOrder()
    fmt.Print(n.value, " ")
    n.right.InOrder()
}

func main() {
    var root *TreeNode
    values := []int{5, 3, 8, 1, 4, 7, 9}
    for _, v := range values {
        root = root.Insert(v)
    }
    fmt.Println("In-order traversal:")
    root.InOrder()
    fmt.Println()
}

