// DynamicArray: بنية بسيطة تحاكي المصفوفة الديناميكية
// نستخدم شريحة جاهزة لكن نغلفها بعملياتنا

type DynamicArray struct {
    data []int
}

func NewDynamicArray() *DynamicArray {
    return &DynamicArray{data: make([]int, 0)}
}

func (d *DynamicArray) Add(val int) {
    d.data = append(d.data, val)
}

func (d *DynamicArray) RemoveAt(index int) bool {
    if index < 0 || index >= len(d.data) {
        return false
    }
    // نزيل العنصر بإعادة بناء الشريحة
    d.data = append(d.data[:index], d.data[index+1:]...)
    return true
}

func (d *DynamicArray) Get(index int) (int, bool) {
    if index < 0 || index >= len(d.data) {
        return 0, false
    }
    return d.data[index], true
}

func (d *DynamicArray) Size() int {
    return len(d.data)
}

func main() {
    arr := NewDynamicArray()
    arr.Add(10)
    arr.Add(20)
    arr.Add(30)
    fmt.Println("Size:", arr.Size())
    if val, ok := arr.Get(1); ok {
        fmt.Println("Element at index 1:", val)
    }
    arr.RemoveAt(1)
    fmt.Println("After removal, size:", arr.Size())
    if val, ok := arr.Get(1); ok {
        fmt.Println("Element at index 1 now:", val)
    }
}

