import "fmt"

type Graph struct {
	adj map[int][]int
}

func NewGraph() *Graph {
	return &Graph{adj: make(map[int][]int)}
}

func (g *Graph) AddEdge(u, v int) {
	g.adj[u] = append(g.adj[u], v)
	g.adj[v] = append(g.adj[v], u) // نضيف الاتجاهين
}

func (g *Graph) DFS(start int) []int {
	visited := make(map[int]bool)
	result := []int{}
	var dfs func(int)
	dfs = func(node int) {
		visited[node] = true
		result = append(result, node)
		for _, neighbor := range g.adj[node] {
			if !visited[neighbor] {
				dfs(neighbor)
			}
		}
	}
	dfs(start)
	return result
}

func main() {
	g := NewGraph()
	g.AddEdge(1, 2)
	g.AddEdge(1, 3)
	g.AddEdge(2, 4)
	g.AddEdge(3, 4)
	fmt.Println(g.DFS(1))
}

