import "fmt"

func main() {
	// 2x3 matrix A
	A := [][]int{
		{1, 2, 3},
		{4, 5, 6},
	}
	// 3x2 matrix B
	B := [][]int{
		{7, 8},
		{9, 10},
		{11, 12},
	}

	rowsA, colsA := len(A), len(A[0])
	rowsB, colsB := len(B), len(B[0])
	if colsA != rowsB {
		fmt.Println("Cannot multiply: incompatible dimensions")
		return
	}

	// Result matrix has dimensions rowsA x colsB
	result := make([][]int, rowsA)
	for i := range result {
		result[i] = make([]int, colsB)
	}

	// Multiply: sum of products over the shared dimension
	for i := 0; i < rowsA; i++ {
		for j := 0; j < colsB; j++ {
			sum := 0
			for k := 0; k < colsA; k++ {
				sum += A[i][k] * B[k][j]
			}
			result[i][j] = sum
		}
	}

	// Print result matrix
	for _, row := range result {
		for _, val := range row {
			fmt.Printf("%d ", val)
		}
		fmt.Println()
	}
}

