)

func isPerfect(n int) bool {
	if n < 2 {
		return false
	}
	sum := 1
	// لماذا؟ نفحص حتى الجذر التربيعي فقط لتسريع البحث
	for i := 2; i <= int(math.Sqrt(float64(n))); i++ {
		if n%i == 0 {
			sum += i
			if i != n/i {
				sum += n / i
			}
		}
	}
	return sum == n
}

func main() {
	// لماذا؟ نبحث في نطاق صغير لأن الأعداد المثالية نادرة
	for n := 1; n <= 10000; n++ {
		if isPerfect(n) {
			fmt.Println(n)
		}
	}
}

