func toPigLatin(word string) string {
	vowels := "aeiouAEIOU"
	if strings.ContainsRune(vowels, rune(word[0])) {
		return word + "way"
	}
	// نجد أول حرف متحرك
	for i := 0; i < len(word); i++ {
		if strings.ContainsRune(vowels, rune(word[i])) {
			return word[i:] + word[:i] + "ay"
		}
	}
	return word + "ay"
}

func main() {
	words := []string{"hello", "apple", "world"}
	for _, w := range words {
		fmt.Println(toPigLatin(w))
	}
}

