import "fmt"

// sieve returns a slice of booleans where true means prime.
func sieve(n int) []bool {
	isPrime := make([]bool, n+1)
	for i := 2; i <= n; i++ {
		isPrime[i] = true
	}
	// Start from 2; mark multiples as non-prime.
	for p := 2; p*p <= n; p++ {
		if isPrime[p] {
			for multiple := p * p; multiple <= n; multiple += p {
				isPrime[multiple] = false
			}
		}
	}
	return isPrime
}

func main() {
	limit := 30
	primes := sieve(limit)
	fmt.Print("Primes up to ", limit, ":")
	for num, ok := range primes {
		if ok {
			fmt.Print(" ", num)
		}
	}
	fmt.Println()
}

