import "fmt"

type Queue struct {
	buf  [5]int
	head int
	tail int
	size int
}

func (q *Queue) Enqueue(v int) {
	if q.size == len(q.buf) {
		panic("queue full")
	}
	q.buf[q.tail] = v
	q.tail = (q.tail + 1) % len(q.buf) // نلتفّ للبداية
	q.size++
}

func (q *Queue) Dequeue() int {
	if q.size == 0 {
		panic("queue empty")
	}
	v := q.buf[q.head]
	q.head = (q.head + 1) % len(q.buf)
	q.size--
	return v
}

func main() {
	q := Queue{}
	q.Enqueue(1)
	q.Enqueue(2)
	q.Enqueue(3)
	fmt.Println(q.Dequeue())
	q.Enqueue(4)
	q.Enqueue(5)
	q.Enqueue(6) // يلتفّ المؤشر
	for q.size > 0 {
		fmt.Println(q.Dequeue())
	}
}

