import "fmt"

// partition تقسم المقطع وتعيد فهرس المحور
func partition(arr []int, low, high int) int {
	pivot := arr[low+(high-low)/2] // اختيار محور وسط
	i, j := low-1, high+1
	for {
		for {
			i++
			if arr[i] >= pivot {
				break
			}
		}
		for {
			j--
			if arr[j] <= pivot {
				break
			}
		}
		if i >= j {
			return j
		}
		arr[i], arr[j] = arr[j], arr[i] // تبادل العنصرين
	}
}

func quickSort(arr []int, low, high int) {
	if low < high {
		p := partition(arr, low, high)
		quickSort(arr, low, p)   // الفرز العودي للنصف الأيسر
		quickSort(arr, p+1, high) // الفرز العودي للنصف الأيمن
	}
}

func main() {
	arr := []int{9, -3, 5, 2, 6, 8, -6, 1, 3}
	quickSort(arr, 0, len(arr)-1)
	fmt.Println(arr)
}

