// Node: عقدة القائمة تحتوي قيمة ومؤشراً للعقدة التالية
type Node struct {
    value int
    next  *Node
}

// LinkedList: بنية القائمة تحتفظ برأس القائمة
type LinkedList struct {
    head *Node
}

// InsertAtHead: إضافة عقدة جديدة في بداية القائمة
func (l *LinkedList) InsertAtHead(val int) {
    newNode := &Node{value: val, next: l.head}
    l.head = newNode
}

// Print: طباعة عناصر القائمة بالترتيب
func (l *LinkedList) Print() {
    current := l.head
    for current != nil {
        fmt.Print(current.value, " ")
        current = current.next
    }
    fmt.Println()
}

func main() {
    list := &LinkedList{}
    list.InsertAtHead(3)
    list.InsertAtHead(2)
    list.InsertAtHead(1)
    fmt.Println("List contents:")
    list.Print()
}

