type Stack []int

func (s *Stack) Push(v int) {
	*s = append(*s, v) // نضيف للآخر
}

func (s *Stack) Pop() int {
	n := len(*s)
	v := (*s)[n-1]
	*s = (*s)[:n-1] // نحذف الأخير
	return v
}

func (s Stack) Peek() int {
	return s[len(s)-1]
}

func main() {
