	st.Push(10)
	st.Push(20)
	st.Push(30)
	fmt.Println("Top:", st.Peek())
	fmt.Println("Pop:", st.Pop())
	fmt.Println("Pop:", st.Pop())
	fmt.Println("Size:", len(st))
}

