import "fmt"

// الحقولُ خاصّةٌ (أحرفٌ صغيرة) فلا تُقرأ خارجَ الحزمة
type BankAccount struct {
	owner   string
	balance float64
}

// دالةُ إنشاءٍ تُرجع مؤشّراً للصنف
func NewBankAccount(owner string, initial float64) *BankAccount {
	return &BankAccount{owner: owner, balance: initial}
}

// إيداعُ مبلغٍ مع التحققِ من قيمتِه
func (a *BankAccount) Deposit(amount float64) {
	if amount > 0 {
		a.balance += amount
	}
}

// سحبٌ آمنٌ: لا يسمحُ بسحبٍ يزيدُ عن الرصيد
func (a *BankAccount) Withdraw(amount float64) bool {
	if amount > 0 && amount <= a.balance {
		a.balance -= amount
		return true
	}
	return false
}

// دالةُ وصولٍ للرصيد (قراءةٌ فقط)
func (a *BankAccount) Balance() float64 {
	return a.balance
}

func main() {
	acc := NewBankAccount("Sara", 1000)
	acc.Deposit(500)
	ok := acc.Withdraw(200)
	fmt.Printf("Withdraw ok: %v\n", ok)
	fmt.Printf("Balance: %.2f\n", acc.Balance())
}

